const items = $input.all();
if (items.length !== 1) throw new Error('Expected one manually requested bank review');
const response = items[0].json;
if (response.error !== undefined || response.isError === true) {
  throw new Error('The MCP request failed; no completed review is available');
}
let evidence = response.structuredContent;
if (evidence === undefined) {
  const block = response.content?.find(item => item.type === 'text');
  evidence = typeof block?.text === 'string' ? JSON.parse(block.text) : block?.text;
}
if (!evidence || Array.isArray(evidence) || evidence.schema !== 'liquilens.bank-specialisation.v1') {
  throw new Error('Expected the bank-specialisation evidence contract');
}
if (typeof evidence.slug !== 'string' || !evidence.slug ||
    !['observed', 'stale', 'historical', 'unavailable'].includes(evidence.status)) {
  throw new Error('Bank identity or evidence status is missing');
}
if (evidence.scope !== 'research' || evidence.score_authority !== false ||
    evidence.can_authorize_credit !== false) {
  throw new Error('Expected research evidence without score or credit authority');
}
// Keep dates, nulls, sources, eligibility flags and interpretation limits unchanged.
return [{ json: evidence }];
